svg.script:
const NS = 'http://www.w3.org/2000/svg';
const make = (tag, attrs, parent) => { const e = document.createElementNS(NS, tag); for (const k in attrs) e.setAttribute(k, attrs[k]); parent.appendChild(e); return e; };
const ticks = document.getElementById('ticks');
for (let i = 0; i < 120; i++) {
  const a = i * Math.PI / 60, major = i % 10 === 0, mid = i % 5 === 0;
  const r1 = major ? 400 : mid ? 410 : 420, r2 = 438;
  make('line', { x1: 512 + Math.sin(a) * r1, y1: 512 - Math.cos(a) * r1, x2: 512 + Math.sin(a) * r2, y2: 512 - Math.cos(a) * r2 }, ticks);
}
const rose = document.getElementById('rose');
const point = (deg, r) => { const a = deg * Math.PI / 180; return [512 + Math.sin(a) * r, 512 - Math.cos(a) * r]; };
// long cardinal points and shorter diagonal points, each split into a light and a dark half like an engraving
const spokes = [[0, 345, 36], [90, 345, 36], [180, 345, 36], [270, 345, 36], [45, 230, 28], [135, 230, 28], [225, 230, 28], [315, 230, 28]];
spokes.forEach(([deg, len, w], i) => {
  const tip = point(deg, len), left = point(deg - w, 60), right = point(deg + w, 60);
  make('path', { d: `M${tip} L${left} L512,512 Z`, fill: '#9C7A3E', opacity: i < 4 ? .85 : .55, 'stroke-width': 1.7 }, rose);
  make('path', { d: `M${tip} L${right} L512,512 Z`, fill: '#EAD7A0', opacity: i < 4 ? .9 : .7, 'stroke-width': 1.7 }, rose);
});
